<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --page-bg: #0b1020;
      --panel-bg: #151c31;
      --panel-border: #2a3557;
      --text-primary: #f4f7ff;
      --text-secondary: #aeb9d6;
      --accent: #7cc7ff;
      --accent-strong: #5ab7fb;
      --error: #ff8f8f;
      --error-bg: #3d1f2b;
      --input-bg: #0f1528;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(90, 183, 251, 0.12), transparent 35%),
        linear-gradient(180deg, #0b1020 0%, #090d18 100%);
      color: var(--text-primary);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .skip-link {
