      font-weight: 700;
      text-decoration: none;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 2px solid transparent;
      box-shadow: 0 0 0 4px rgba(124, 199, 255, 0.35);
    }

    .page-shell {
      width: min(100%, 560px);
    }

    .support-card {
      background: linear-gradient(180deg, rgba(25, 34, 60, 0.96), rgba(17, 24, 44, 0.98));
      border: 1px solid var(--panel-border);
      border-radius: 22px;
      box-shadow: var(--shadow);
      padding: 32px;
    }

    .eyebrow {
      margin: 0 0 10px;
      font-size: 0.85rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 5vw, 2.5rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
    }

    .required-indicator {
      color: #ffd37a;
    }

    input {
      width: 100%;
      border: 1px solid #35436b;
      border-radius: 14px;
      background: var(--input-bg);
      color: var(--text-primary);
      padding: 14px 16px;
      font-size: 1rem;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #8492b6;
    }

    input:hover {
      border-color: #4a5b8d;
    }

    input:focus-visible {
      outline: 2px solid transparent;
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(124, 199, 255, 0.18);
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
      box-shadow: 0 0 0 4px rgba(255, 143, 143, 0.15);
    }

    .helper-text,
