      border: none;
      border-radius: 999px;
      padding: 14px 20px;
      font: inherit;
      font-weight: 700;
      color: #04111d;
      background: linear-gradient(135deg, #9fdcff 0%, var(--accent-strong) 100%);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 16px 30px rgba(90, 183, 251, 0.28);
    }

    button:hover {
      filter: brightness(1.03);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 2px solid transparent;
      box-shadow:
        0 0 0 4px rgba(124, 199, 255, 0.22),
        0 16px 30px rgba(90, 183, 251, 0.28);
    }

    @media (max-width: 480px) {
      .support-card {
        padding: 24px;
