  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --page-bg: #0b1020;
      --panel-bg: #151c31;
      --panel-border: #2a3557;
      --text-primary: #f4f7ff;
      --text-secondary: #aeb9d6;
      --accent: #7cc7ff;
      --accent-strong: #5ab7fb;
      --error: #ff8f8f;
      --error-bg: #3d1f2b;
      --input-bg: #0f1528;
      --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(90, 183, 251, 0.12), transparent 35%),
        linear-gradient(180deg, #0b1020 0%, #090d18 100%);
      color: var(--text-primary);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .skip-link {
      position: absolute;
      left: 16px;
      top: 16px;
      transform: translateY(-200%);
      padding: 10px 14px;
      border-radius: 10px;
      background: #ffffff;
      color: #04111d;
      font-weight: 700;
      text-decoration: none;
      z-index: 10;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 2px solid transparent;
      box-shadow: 0 0 0 4px rgba(124, 199, 255, 0.35);
    }

    .page-shell {
      width: min(100%, 560px);
    }

    .support-card {
      background: linear-gradient(180deg, rgba(25, 34, 60, 0.96), rgba(17, 24, 44, 0.98));
      border: 1px solid var(--panel-border);
      border-radius: 22px;
      box-shadow: var(--shadow);
      padding: 32px;
    }

    .eyebrow {
      margin: 0 0 10px;
      font-size: 0.85rem;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--accent);
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 5vw, 2.5rem);
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
    }

    .required-indicator {
      color: #ffd37a;
    }

    input {
      width: 100%;
      border: 1px solid #35436b;
      border-radius: 14px;
      background: var(--input-bg);
      color: var(--text-primary);
      padding: 14px 16px;
      font-size: 1rem;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #8492b6;
    }

    input:hover {
      border-color: #4a5b8d;
    }

    input:focus-visible {
      outline: 2px solid transparent;
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(124, 199, 255, 0.18);
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
      box-shadow: 0 0 0 4px rgba(255, 143, 143, 0.15);
    }

    .helper-text,
    .validation-message,
    .form-status {
      font-size: 0.95rem;
      line-height: 1.5;
    }

    .helper-text {
      color: var(--text-secondary);
    }

    .validation-message {
      color: var(--error);
      min-height: 1.5em;
    }

    .form-status {
      min-height: 1.5em;
      color: #8ce3af;
    }

    .form-status[data-tone="error"] {
      color: var(--error);
    }

    button {
      appearance: none;
      border: none;
      border-radius: 999px;
      padding: 14px 20px;
      font: inherit;
      font-weight: 700;
      color: #04111d;
      background: linear-gradient(135deg, #9fdcff 0%, var(--accent-strong) 100%);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 16px 30px rgba(90, 183, 251, 0.28);
    }

    button:hover {
      filter: brightness(1.03);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 2px solid transparent;
      box-shadow:
        0 0 0 4px rgba(124, 199, 255, 0.22),
        0 16px 30px rgba(90, 183, 251, 0.28);
    }

    @media (max-width: 480px) {
      .support-card {
        padding: 24px;
      }
    }

    @media (forced-colors: active) {
      body {
        background: Canvas;
      }

      .skip-link {
        background: ButtonFace;
        color: ButtonText;
        border: 1px solid ButtonText;
      }

      .support-card {
        background: Canvas;
        border-color: ButtonText;
        box-shadow: none;
      }

      input,
      button {
        forced-color-adjust: auto;
        border: 1px solid ButtonText;
      }

      .helper-text,
      .intro,
      .validation-message,
      .form-status,
      .eyebrow {
        color: CanvasText;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>
  <div id="app"></div>

  <script>
    const fields = [
      {
        name: "fullName",
        label: "Full name",
        type: "text",
        required: true,
        autocomplete: "name",
        placeholder: "Jordan Lee"
      },
      {
        name: "email",
        label: "Email address",
        type: "email",
        required: true,
        autocomplete: "email",
        placeholder: "jordan@example.com"
      },
      {
        name: "phone",
        label: "Phone number",
        type: "tel",
        required: false,
        autocomplete: "tel",
        placeholder: "(555) 123-4567",
        helperText: "Optional. Enter 10-15 digits, and you may include spaces, parentheses, or dashes."
      }
    ];

    const validationState = {
      fullName: "",
      email: "",
      phone: ""
    };

    const patterns = {
      email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    };

    function FieldComponent(field) {
      const helperId = field.helperText ? field.name + "-helper" : "";
      const errorId = field.name + "-error";
      const describedBy = [helperId, errorId].filter(Boolean).join(" ");
      const requiredIndicator = field.required
        ? '<span class="required-indicator" aria-hidden="true"> *</span>'
        : "";

      return `
        <div class="form-field">
          <label for="${field.name}">${field.label}${requiredIndicator}</label>
          <input
            id="${field.name}"
            name="${field.name}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
            placeholder="${field.placeholder}"
            ${field.required ? "required" : ""}
            aria-required="${field.required ? "true" : "false"}"
            aria-invalid="false"
            aria-describedby="${describedBy}"
          />
          ${field.helperText ? `<div class="helper-text" id="${helperId}">${field.helperText}</div>` : ""}
          <div class="validation-message" id="${errorId}" aria-live="polite"></div>
        </div>
      `;
    }

    function SupportPage() {
      return `
        <main class="page-shell" id="main-content">
          <section class="support-card" aria-labelledby="support-heading">
            <p class="eyebrow">Support</p>
            <h1 id="support-heading">How can we help?</h1>
            <p class="intro">
              Send our team a message and we will follow up as soon as possible.
            </p>
            <form id="support-form" novalidate>
              ${fields.map(FieldComponent).join("")}
              <button type="submit">Submit request</button>
              <div class="form-status" id="form-status" aria-live="polite"></div>
            </form>
          </section>
        </main>
      `;
    }

    function renderApp() {
      document.getElementById("app").innerHTML = SupportPage();
      const form = document.getElementById("support-form");

      fields.forEach((field) => {
        const input = document.getElementById(field.name);
        input.addEventListener("input", () => {
          validateField(field.name);
        });
        input.addEventListener("blur", () => validateField(field.name));
      });

      form.addEventListener("submit", handleSubmit);
    }

    function validateField(fieldName) {
      const field = fields.find((item) => item.name === fieldName);
      const input = document.getElementById(fieldName);
      const error = getFieldError(field, input.value.trim());
      const errorNode = document.getElementById(fieldName + "-error");

      validationState[fieldName] = error;
      input.setAttribute("aria-invalid", error ? "true" : "false");
      errorNode.textContent = error;
      return !error;
    }

    function getFieldError(field, rawValue) {
      if (field.required && !rawValue) {
        return field.label + " is required.";
      }

      if (!rawValue) {
        return "";
      }

      if (field.name === "email" && !patterns.email.test(rawValue)) {
        return "Enter a valid email address.";
      }

      if (field.name === "phone" && !patterns.phone.test(rawValue)) {
        const digitCount = rawValue.replace(/\D/g, "").length;
        const hasOnlyAllowedCharacters = /^[+\d\s().-]+$/.test(rawValue);

        if (!hasOnlyAllowedCharacters || digitCount < 10 || digitCount > 15) {
          return "Enter a valid phone number using 10-15 digits.";
        }
      }

      if (field.name === "phone" && rawValue.replace(/\D/g, "").length === 0) {
        return "Enter a valid phone number using 10-15 digits.";
      }

      return "";
    }

    function handleSubmit(event) {
      event.preventDefault();
      const status = document.getElementById("form-status");
      let firstInvalidField = null;

      fields.forEach((field) => {
        const isValid = validateField(field.name);
        if (!isValid && !firstInvalidField) {
          firstInvalidField = document.getElementById(field.name);
        }
      });

      if (firstInvalidField) {
        status.dataset.tone = "error";
        status.textContent = "Please correct the highlighted fields and try again.";
        firstInvalidField.focus();
        return;
      }

      status.dataset.tone = "success";
      status.textContent = "Your request has been submitted.";
      event.target.reset();

      fields.forEach((field) => {
        validationState[field.name] = "";
        document.getElementById(field.name).setAttribute("aria-invalid", "false");
        document.getElementById(field.name + "-error").textContent = "";
      });
    }

    renderApp();
  </script>
</body>
</html>
