   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: dark;
       --page-bg: #0b1020;
       --panel-bg: #151c31;
       --panel-border: #2a3557;
       --text-primary: #f4f7ff;
       --text-secondary: #aeb9d6;
       --accent: #7cc7ff;
       --accent-strong: #5ab7fb;
       --error: #ff8f8f;
       --error-bg: #3d1f2b;
       --input-bg: #0f1528;
       --shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
       background:
         radial-gradient(circle at top, rgba(90, 183, 251, 0.12), transparent 35%),
         linear-gradient(180deg, #0b1020 0%, #090d18 100%);
       color: var(--text-primary);
       display: flex;
       align-items: center;
       justify-content: center;
       padding: 24px;
     }

     .skip-link {
       position: absolute;
       left: 16px;
       top: 16px;
       transform: translateY(-200%);
       padding: 10px 14px;
       border-radius: 10px;
       background: #ffffff;
       color: #04111d;
       font-weight: 700;
       text-decoration: none;
       z-index: 10;
     }

     .skip-link:focus {
       transform: translateY(0);
       outline: 2px solid transparent;
       box-shadow: 0 0 0 4px rgba(124, 199, 255, 0.35);
     }

     .page-shell {
       width: min(100%, 560px);
     }

     .support-card {
       background: linear-gradient(180deg, rgba(25, 34, 60, 0.96), rgba(17, 24, 44, 0.98));
       border: 1px solid var(--panel-border);
       border-radius: 22px;
       box-shadow: var(--shadow);
       padding: 32px;
     }

     .eyebrow {
       margin: 0 0 10px;
       font-size: 0.85rem;
       letter-spacing: 0.08em;
       text-transform: uppercase;
       color: var(--accent);
     }

     h1 {
       margin: 0 0 12px;
       font-size: clamp(2rem, 5vw, 2.5rem);
       line-height: 1.1;
     }

     .intro {
       margin: 0 0 28px;
       color: var(--text-secondary);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 20px;
     }

     .form-field {
       display: grid;
       gap: 8px;
     }

     label {
       font-weight: 600;
     }

     .required-indicator {
       color: #ffd37a;
     }

     input {
       width: 100%;
       border: 1px solid #35436b;
       border-radius: 14px;
       background: var(--input-bg);
       color: var(--text-primary);
       padding: 14px 16px;
       font-size: 1rem;
       transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
     }

     input::placeholder {
       color: #8492b6;
     }

     input:hover {
       border-color: #4a5b8d;
     }

     input:focus-visible {
       outline: 2px solid transparent;
       border-color: var(--accent);
       box-shadow: 0 0 0 4px rgba(124, 199, 255, 0.18);
     }

     input[aria-invalid="true"] {
       border-color: var(--error);
       box-shadow: 0 0 0 4px rgba(255, 143, 143, 0.15);
     }

     .helper-text,
     .validation-message,
     .form-status {
       font-size: 0.95rem;
       line-height: 1.5;
     }

     .helper-text {
       color: var(--text-secondary);
     }

     .validation-message {
       color: var(--error);
       min-height: 1.5em;
     }

     .form-status {
       min-height: 1.5em;
       color: #8ce3af;
     }

     .form-status[data-tone="error"] {
       color: var(--error);
     }

     button {
       appearance: none;
       border: none;
       border-radius: 999px;
       padding: 14px 20px;
       font: inherit;
       font-weight: 700;
       color: #04111d;
       background: linear-gradient(135deg, #9fdcff 0%, var(--accent-strong) 100%);
       cursor: pointer;
       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
       box-shadow: 0 16px 30px rgba(90, 183, 251, 0.28);
     }

     button:hover {
       filter: brightness(1.03);
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 2px solid transparent;
       box-shadow:
         0 0 0 4px rgba(124, 199, 255, 0.22),
         0 16px 30px rgba(90, 183, 251, 0.28);
     }

     @media (max-width: 480px) {
       .support-card {
         padding: 24px;
       }
     }

     @media (forced-colors: active) {
       body {
         background: Canvas;
       }

       .skip-link {
         background: ButtonFace;
         color: ButtonText;
         border: 1px solid ButtonText;
       }

       .support-card {
         background: Canvas;
         border-color: ButtonText;
         box-shadow: none;
       }

       input,
       button {
         forced-color-adjust: auto;
         border: 1px solid ButtonText;
       }

       .helper-text,
       .intro,
       .validation-message,
       .form-status,
       .eyebrow {
         color: CanvasText;
       }
     }
   </style>
 </head>
