     const validationState = {
       fullName: "",
       email: "",
       phone: ""
     };

     const patterns = {
       email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/
     };

     function FieldComponent(field) {
       const helperId = field.helperText ? field.name + "-helper" : "";
       const errorId = field.name + "-error";
       const describedBy = [helperId, errorId].filter(Boolean).join(" ");
       const requiredIndicator = field.required
         ? '<span class="required-indicator" aria-hidden="true"> *</span>'
         : "";

       return `
         <div class="form-field">
           <label for="${field.name}">${field.label}${requiredIndicator}</label>
           <input
             id="${field.name}"
             name="${field.name}"
             type="${field.type}"
             autocomplete="${field.autocomplete}"
             placeholder="${field.placeholder}"
             ${field.required ? "required" : ""}
             aria-required="${field.required ? "true" : "false"}"
             aria-invalid="false"
             aria-describedby="${describedBy}"
           />
           ${field.helperText ? `<div class="helper-text" id="${helperId}">${field.helperText}</div>` : ""}
           <div class="validation-message" id="${errorId}" aria-live="polite"></div>
         </div>
       `;
     }

     function SupportPage() {
       return `
         <main class="page-shell" id="main-content">
           <section class="support-card" aria-labelledby="support-heading">
             <p class="eyebrow">Support</p>
             <h1 id="support-heading">How can we help?</h1>
             <p class="intro">
               Send our team a message and we will follow up as soon as possible.
             </p>
             <form id="support-form" novalidate>
               ${fields.map(FieldComponent).join("")}
               <button type="submit">Submit request</button>
               <div class="form-status" id="form-status" aria-live="polite"></div>
             </form>
           </section>
         </main>
       `;
     }

     function renderApp() {
       document.getElementById("app").innerHTML = SupportPage();
       const form = document.getElementById("support-form");

       fields.forEach((field) => {
         const input = document.getElementById(field.name);
         input.addEventListener("input", () => {
           validateField(field.name);
         });
         input.addEventListener("blur", () => validateField(field.name));
       });

       form.addEventListener("submit", handleSubmit);
     }

     function validateField(fieldName) {
       const field = fields.find((item) => item.name === fieldName);
       const input = document.getElementById(fieldName);
       const error = getFieldError(field, input.value.trim());
       const errorNode = document.getElementById(fieldName + "-error");

       validationState[fieldName] = error;
       input.setAttribute("aria-invalid", error ? "true" : "false");
       errorNode.textContent = error;
       return !error;
     }

     function getFieldError(field, rawValue) {
       if (field.required && !rawValue) {
         return field.label + " is required.";
       }

       if (!rawValue) {
         return "";
       }

       if (field.name === "email" && !patterns.email.test(rawValue)) {
         return "Enter a valid email address.";
       }

       if (field.name === "phone" && !patterns.phone.test(rawValue)) {
         const digitCount = rawValue.replace(/\D/g, "").length;
         const hasOnlyAllowedCharacters = /^[+\d\s().-]+$/.test(rawValue);

         if (!hasOnlyAllowedCharacters || digitCount < 10 || digitCount > 15) {
           return "Enter a valid phone number using 10-15 digits.";
         }
       }

       if (field.name === "phone" && rawValue.replace(/\D/g, "").length === 0) {
         return "Enter a valid phone number using 10-15 digits.";
       }

       return "";
     }

     function handleSubmit(event) {
       event.preventDefault();
       const status = document.getElementById("form-status");
       let firstInvalidField = null;

       fields.forEach((field) => {
         const isValid = validateField(field.name);
         if (!isValid && !firstInvalidField) {
           firstInvalidField = document.getElementById(field.name);
         }
       });

       if (firstInvalidField) {
         status.dataset.tone = "error";
         status.textContent = "Please correct the highlighted fields and try again.";
         firstInvalidField.focus();
         return;
       }

       status.dataset.tone = "success";
       status.textContent = "Your request has been submitted.";
       event.target.reset();

       fields.forEach((field) => {
         validationState[field.name] = "";
         document.getElementById(field.name).setAttribute("aria-invalid", "false");
         document.getElementById(field.name + "-error").textContent = "";
       });
     }

     renderApp();
   </script>
